     AND ali.PROCESS_DEFINITION_KEY = #{query.processDefinitionKey, jdbcType=VARCHAR}


     AND ali.NAME = #{query.name, jdbcType=VARCHAR}


     AND ali.RESOURCE_NAME = #{query.resourceName, jdbcType=VARCHAR}


     AND ali.BPMN_XML = #{query.bpmnXml, jdbcType=VARCHAR}


     AND ali.TENANT_ID = #{query.tenantId, jdbcType=VARCHAR}


     AND ali.VERSION = #{query.version, jdbcType=INTEGER}


     AND ali.VERSION_TAG = #{query.versionTag, jdbcType=VARCHAR}


     AND ali.FORM_ID = #{query.formId, jdbcType=VARCHAR}

